async def workflow(task):
    result = await agent(
        role="geneticist",
        instruction="Work as the sole specialist for this multiple-choice problem. First parse the exact question, requested answer count, and every option, including negations such as \"NOT supported\", \"incorrect\", and \"all of the above\". Independently establish the relevant facts using appropriate authoritative sources or domain tools when available; prioritize primary studies, registries, curated datasets, and official documentation, and distinguish direct evidence from inference. Evaluate each option against the question rather than selecting by familiarity, reject unsupported claims, then check that the chosen set has the requested size and answers the exact wording. Return the option letter(s), the option text, a concise evidence-based justification for each selection, and brief reasons for rejecting close alternatives. Include source names or identifiers and dates when retrievable; state uncertainty or unavailable evidence instead of inventing details. Do not assume any candidate or answer in advance. Give a sound paired bulk RNA-seq analysis plan: sample/metadata validation, QC, paired differential model, effect sizes and FDR, pathway analysis, immune/stromal estimates, and clinical covariates. Reject statements that omit essential QC or overclaim causality.",
        input=task,
    )
    return result
